"""Argmax-inversion certificate and critical-band locator for a quantised key cache.

Given the top-two logit gap g of an attention row and a key-noise amplitude A that halves
with each stored bit (noise at width b is A / 2^b), this module decides, per bit width,
whether the quantised row is safe, critical, or inverted, and certifies a LOWER bound on
the attention output error whenever inversion occurs.
"""

from __future__ import annotations

import math
from typing import Dict, List, Optional


def noise_at_width(amplitude: float, bits: int) -> float:
    """Key-noise magnitude A / 2^b at bit width b."""
    return amplitude / 2.0 ** bits


def inversion_lower_bound(overshoot_half: float) -> float:
    """Guaranteed output error 1/2 - 1/(1 + exp(2h)) when the noise overshoots by 2h."""
    return 0.5 - 1.0 / (1.0 + math.exp(2.0 * overshoot_half))


def classify_width(amplitude: float, gap: float, bits: int) -> Dict[str, object]:
    """Classify a single bit width as 'inverted', 'critical' or 'safe', with a certificate.

    'inverted': noise >= gap, the argmax flips and the certified error is
                1/2 - 1/(1 + exp(2h)) with 2h = noise - gap.
    'critical': gap/2 <= noise < gap -- one bit from disaster.
    'safe'    : noise < gap/2.
    """
    noise = noise_at_width(amplitude, bits)
    if noise >= gap:
        h = 0.5 * (noise - gap)
        return {"bits": bits, "noise": noise, "status": "inverted",
                "certified_error_lower_bound": inversion_lower_bound(h)}
    if noise >= gap / 2.0:
        return {"bits": bits, "noise": noise, "status": "critical",
                "certified_error_lower_bound": 0.0}
    return {"bits": bits, "noise": noise, "status": "safe",
            "certified_error_lower_bound": 0.0}


def critical_width(amplitude: float, gap: float, max_bits: int = 32) -> Optional[int]:
    """The unique bit width b with A/2^b in [g/2, g), if it exists.

    Uniqueness is guaranteed: one bit lower the noise beats the gap, one bit higher it is
    already below half the gap.  Computed directly as ceil(log2(A/g)), then verified.
    Complexity O(1).
    """
    if amplitude <= 0.0 or gap <= 0.0:
        return None
    b = math.ceil(math.log2(amplitude / gap))
    if b < 0 or b > max_bits:
        return None
    noise = noise_at_width(amplitude, b)
    return b if gap / 2.0 <= noise < gap else None


def bit_ladder_report(amplitude: float, gap: float, widths: List[int]) -> List[Dict[str, object]]:
    """Classify a whole ladder of bit widths.  Complexity O(len(widths))."""
    return [classify_width(amplitude, gap, b) for b in widths]


if __name__ == "__main__":
    amplitude, gap = 30.0, 0.9
    for row in bit_ladder_report(amplitude, gap, list(range(2, 11))):
        print(f"  b={row['bits']:2d}  noise={row['noise']:8.4f}  {row['status']:8s}"
              f"  certified error >= {row['certified_error_lower_bound']:.4f}")
    print(f"unique critical width: {critical_width(amplitude, gap)}")
